import { QueryClient, QueryClientProvider, useQuery } from "@tanstack/react-query";

const client = new QueryClient();
async function loadTodos(): Promise<{ id: string }[]> { return [{ id: "t1" }]; }
function TodoCount() {
  const query = useQuery({ queryKey: ["todos"], queryFn: loadTodos });
  if (query.isPending) return <p>Loading</p>;
  if (query.isError) return <p>Failed</p>;
  return <p>{query.data.length} todos</p>;
}
export function App() {
  return <QueryClientProvider client={client}><TodoCount /></QueryClientProvider>;
}

import { useMutation, useQueryClient } from "@tanstack/react-query";

type Todo = { id: string; title: string };
export function useCreateTodo(save: (title: string) => Promise<Todo>) {
  const client = useQueryClient();
  return useMutation({
    mutationFn: save,
    onSuccess: () => client.invalidateQueries({ queryKey: ["todos"] }),
  });
}

